import asyncio
import json
import socket
import threading
import uuid
from datetime import datetime, timezone

from aiohttp import web
from websockets.sync.server import ServerConnection, ServerProtocol


class ClientRegistry:
    def __init__(self):
        self._clients = {}
        self._lock = threading.Lock()

    def add(self, client_id, ws):
        with self._lock:
            self._clients[client_id] = ws

    def remove(self, client_id):
        with self._lock:
            return self._clients.pop(client_id, None)

    def get(self, client_id):
        with self._lock:
            return self._clients.get(client_id)

    def count(self):
        with self._lock:
            return len(self._clients)

    def all_items(self):
        with self._lock:
            return list(self._clients.items())

    def item_ids(self):
        with self._lock:
            return list(self._clients.keys())

    def clear(self):
        with self._lock:
            self._clients.clear()


class ChannelManager:
    def __init__(self):
        self._channels = {}
        self._lock = threading.Lock()

    def subscribe(self, client_id, channel):
        with self._lock:
            if channel not in self._channels:
                self._channels[channel] = set()
            self._channels[channel].add(client_id)

    def unsubscribe(self, client_id, channel):
        with self._lock:
            if channel in self._channels:
                self._channels[channel].discard(client_id)
                if not self._channels[channel]:
                    del self._channels[channel]

    def unsubscribe_all(self, client_id):
        with self._lock:
            for channel in list(self._channels.keys()):
                self._channels[channel].discard(client_id)
                if not self._channels[channel]:
                    del self._channels[channel]

    def get_subscribers(self, channel):
        with self._lock:
            subscribers = self._channels.get(channel, set())
            return list(subscribers)

    def list_channels(self):
        with self._lock:
            return {name: len(subscribers) for name, subscribers in self._channels.items()}

    def clear(self):
        with self._lock:
            self._channels.clear()


_registry = ClientRegistry()
_channels = ChannelManager()
_send_lock = threading.Lock()


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def make_message(msg_type, payload, from_id=None):
    msg = {"type": msg_type, "payload": payload, "timestamp": now_iso()}
    if from_id:
        msg["from"] = from_id
    return json.dumps(msg)


def handle_client(conn):
    client_id = str(uuid.uuid4())
    protocol = ServerProtocol()
    ws = None
    try:
        ws = ServerConnection(conn, protocol)
        ws.handshake()
        _registry.add(client_id, ws)

        ws.send(make_message("system", {"client_id": client_id, "message": "Connected"}))

        for raw_message in ws:
            try:
                data = json.loads(raw_message)
            except json.JSONDecodeError:
                continue

            msg_type = data.get("type", "broadcast")
            payload = data.get("payload", {})

            if msg_type == "subscribe":
                channel = payload.get("channel")
                if channel:
                    _channels.subscribe(client_id, channel)

            elif msg_type == "unsubscribe":
                channel = payload.get("channel")
                if channel:
                    _channels.unsubscribe(client_id, channel)

            elif msg_type == "broadcast":
                msg = make_message("broadcast", payload, from_id=client_id)
                channel = data.get("channel")
                if channel:
                    subscriber_ids = _channels.get_subscribers(channel)
                    with _send_lock:
                        for cid in subscriber_ids:
                            cws = _registry.get(cid)
                            if cws:
                                try:
                                    cws.send(msg)
                                except Exception:
                                    _registry.remove(cid)
                else:
                    with _send_lock:
                        for cid, cws in _registry.all_items():
                            try:
                                cws.send(msg)
                            except Exception:
                                _registry.remove(cid)

            elif msg_type == "direct":
                target = payload.get("target")
                if target:
                    msg = make_message("direct", payload, from_id=client_id)
                    with _send_lock:
                        target_ws = _registry.get(target)
                        if target_ws:
                            try:
                                target_ws.send(msg)
                            except Exception:
                                _registry.remove(target)

    except Exception:
        pass
    finally:
        _channels.unsubscribe_all(client_id)
        _registry.remove(client_id)
        disc_msg = make_message("system", {"client_id": client_id, "message": "Disconnected"})
        with _send_lock:
            for cid, cws in _registry.all_items():
                try:
                    cws.send(disc_msg)
                except Exception:
                    _registry.remove(cid)
        if ws is not None:
            try:
                ws.close()
            except Exception:
                pass
        try:
            conn.close()
        except Exception:
            pass


async def health_handler(request):
    return web.json_response({"clients": _registry.count()})


async def channels_handler(request):
    return web.json_response(_channels.list_channels())


async def channel_subscribers_handler(request):
    channel_name = request.match_info["name"]
    subscribers = _channels.get_subscribers(channel_name)
    return web.json_response(subscribers)


def run_ws_acceptor(host, port):
    sock = socket.create_server((host, port), reuse_port=True)
    sock.listen()

    def accept_loop():
        try:
            while True:
                conn, addr = sock.accept()
                thread = threading.Thread(target=handle_client, args=(conn,), daemon=True)
                thread.start()
        except Exception:
            pass
        finally:
            try:
                sock.close()
            except Exception:
                pass

    accept_thread = threading.Thread(target=accept_loop, name="ws-acceptor", daemon=True)
    accept_thread.start()
    return accept_thread


def start_server(host="0.0.0.0", ws_port=8765, http_port=8080):
    ws_thread = run_ws_acceptor(host, ws_port)

    async def run_http():
        app = web.Application()
        app.router.add_get("/health", health_handler)
        app.router.add_get("/channels", channels_handler)
        app.router.add_get("/channels/{name}/subscribers", channel_subscribers_handler)
        runner = web.AppRunner(app)
        await runner.setup()
        site = web.TCPSite(runner, host, http_port)
        await site.start()
        await asyncio.Future()

    def run_http_thread():
        asyncio.run(run_http())

    http_thread = threading.Thread(target=run_http_thread, name="http-server", daemon=True)
    http_thread.start()

    return ws_thread, http_thread


if __name__ == "__main__":
    start_server()
    try:
        threading.Event().wait()
    except KeyboardInterrupt:
        pass

import asyncio
import json
import time

import pytest
import websockets
from aiohttp import ClientSession

from server import start_server, _registry, _channels

HOST = "127.0.0.1"
WS_PORT = 18765
HTTP_PORT = 18080


@pytest.fixture(autouse=True)
def reset_registry():
    _registry.clear()
    _channels.clear()
    yield
    _registry.clear()
    _channels.clear()


@pytest.fixture(scope="module")
def server():
    t1, t2 = start_server(HOST, WS_PORT, HTTP_PORT)
    time.sleep(0.3)
    yield
    # Daemon threads, nothing to explicitly stop


class TestHealthEndpoint:
    @pytest.mark.asyncio
    async def test_health_returns_zero_when_no_clients(self, server):
        async with ClientSession() as session:
            async with session.get(f"http://{HOST}:{HTTP_PORT}/health") as resp:
                assert resp.status == 200
                data = await resp.json()
                assert data["clients"] == 0

    @pytest.mark.asyncio
    async def test_health_reflects_connected_clients(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1:
            await ws1.recv()
            async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
                await ws2.recv()
                await asyncio.sleep(0.1)
                async with ClientSession() as session:
                    async with session.get(f"http://{HOST}:{HTTP_PORT}/health") as resp:
                        data = await resp.json()
                        assert data["clients"] == 2


class TestClientConnection:
    @pytest.mark.asyncio
    async def test_connect_receives_welcome_message(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            raw = await ws.recv()
            data = json.loads(raw)
            assert data["type"] == "system"
            assert "client_id" in data["payload"]
            assert data["payload"]["message"] == "Connected"
            assert "timestamp" in data

    @pytest.mark.asyncio
    async def test_connect_assigns_unique_ids(self, server):
        ids = set()
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1:
            d1 = json.loads(await ws1.recv())
            ids.add(d1["payload"]["client_id"])
            async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
                d2 = json.loads(await ws2.recv())
                ids.add(d2["payload"]["client_id"])
        assert len(ids) == 2

    @pytest.mark.asyncio
    async def test_disconnect_removes_client(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            await ws.recv()
            assert _registry.count() == 1
        await asyncio.sleep(0.2)
        assert _registry.count() == 0


class TestBroadcast:
    @pytest.mark.asyncio
    async def test_broadcast_delivers_to_all(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            await ws1.recv()
            await ws2.recv()

            await ws1.send(json.dumps({
                "type": "broadcast",
                "payload": {"text": "hello all"}
            }))

            msg2_raw = await asyncio.wait_for(ws2.recv(), timeout=2)
            msg2 = json.loads(msg2_raw)
            assert msg2["type"] == "broadcast"
            assert msg2["payload"]["text"] == "hello all"

    @pytest.mark.asyncio
    async def test_broadcast_sender_does_not_receive_own_message(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            d1 = json.loads(await ws1.recv())
            sender_id = d1["payload"]["client_id"]
            await ws2.recv()

            await ws1.send(json.dumps({
                "type": "broadcast",
                "payload": {"text": "hello"}
            }))

            msg = json.loads(await asyncio.wait_for(ws2.recv(), timeout=2))
            assert msg["from"] == sender_id


class TestDirectMessage:
    @pytest.mark.asyncio
    async def test_direct_message_delivers_to_target(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws3:
            d1 = json.loads(await ws1.recv())
            d2 = json.loads(await ws2.recv())
            d3 = json.loads(await ws3.recv())

            target_id = d2["payload"]["client_id"]

            await ws1.send(json.dumps({
                "type": "direct",
                "payload": {"target": target_id, "text": "secret"}
            }))

            msg = json.loads(await asyncio.wait_for(ws2.recv(), timeout=2))
            assert msg["type"] == "direct"
            assert msg["payload"]["text"] == "secret"
            assert msg["from"] == d1["payload"]["client_id"]

            with pytest.raises(asyncio.TimeoutError):
                await asyncio.wait_for(ws3.recv(), timeout=0.5)


class TestDisconnectNotification:
    @pytest.mark.asyncio
    async def test_disconnect_notifies_remaining_clients(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1:
            d1 = json.loads(await ws1.recv())
            async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
                d2 = json.loads(await ws2.recv())
                # Close ws2
                await ws2.close()
                await asyncio.sleep(0.2)
                # ws1 should receive disconnect notification for ws2's client_id
                notify = json.loads(await asyncio.wait_for(ws1.recv(), timeout=3))
                assert notify["type"] == "system"
                assert notify["payload"]["message"] == "Disconnected"
                assert notify["payload"]["client_id"] == d2["payload"]["client_id"]


class TestMessageFormat:
    @pytest.mark.asyncio
    async def test_message_has_required_fields(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            await ws1.recv()
            await ws2.recv()

            await ws1.send(json.dumps({
                "type": "broadcast",
                "payload": {"text": "check format"}
            }))

            msg = json.loads(await asyncio.wait_for(ws2.recv(), timeout=2))
            assert "type" in msg
            assert "payload" in msg
            assert "timestamp" in msg
            assert msg["type"] == "broadcast"

    @pytest.mark.asyncio
    async def test_invalid_json_is_gracefully_ignored(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            await ws1.recv()
            await ws2.recv()

            await ws1.send("not json")

            with pytest.raises(asyncio.TimeoutError):
                await asyncio.wait_for(ws2.recv(), timeout=0.5)


class TestThreadSafety:
    @pytest.mark.asyncio
    async def test_concurrent_connections(self, server):
        async def connect_and_send():
            async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
                await ws.recv()
                await ws.send(json.dumps({
                    "type": "broadcast",
                    "payload": {"text": "concurrent"}
                }))

        tasks = [asyncio.create_task(connect_and_send()) for _ in range(10)]
        await asyncio.gather(*tasks)
        await asyncio.sleep(0.2)
        assert _registry.count() == 0


class TestSystemMessage:
    @pytest.mark.asyncio
    async def test_system_message_on_connect(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            msg = json.loads(await ws.recv())
            assert msg["type"] == "system"
            assert msg["payload"]["message"] == "Connected"


class TestChannelsEndpoint:
    @pytest.mark.asyncio
    async def test_channels_returns_empty_when_no_subscriptions(self, server):
        async with ClientSession() as session:
            async with session.get(f"http://{HOST}:{HTTP_PORT}/channels") as resp:
                assert resp.status == 200
                data = await resp.json()
                assert data == {}

    @pytest.mark.asyncio
    async def test_channels_returns_active_channels(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            await ws1.recv()
            await ws2.recv()

            await ws1.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await ws2.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await ws2.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "chat"}
            }))
            await asyncio.sleep(0.1)

            async with ClientSession() as session:
                async with session.get(f"http://{HOST}:{HTTP_PORT}/channels") as resp:
                    assert resp.status == 200
                    data = await resp.json()
                    assert data == {"alerts": 2, "chat": 1}

    @pytest.mark.asyncio
    async def test_channels_removes_channel_when_no_subscribers(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            await ws.recv()
            await ws.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "temp"}
            }))
            await asyncio.sleep(0.1)
            await ws.send(json.dumps({
                "type": "unsubscribe",
                "payload": {"channel": "temp"}
            }))
            await asyncio.sleep(0.1)

            async with ClientSession() as session:
                async with session.get(f"http://{HOST}:{HTTP_PORT}/channels") as resp:
                    data = await resp.json()
                    assert "temp" not in data


class TestChannelSubscribersEndpoint:
    @pytest.mark.asyncio
    async def test_channel_subscribers_lists_ids(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            d1 = json.loads(await ws1.recv())
            d2 = json.loads(await ws2.recv())
            cid1 = d1["payload"]["client_id"]
            cid2 = d2["payload"]["client_id"]

            await ws1.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await ws2.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)

            async with ClientSession() as session:
                async with session.get(f"http://{HOST}:{HTTP_PORT}/channels/alerts/subscribers") as resp:
                    assert resp.status == 200
                    data = await resp.json()
                    assert set(data) == {cid1, cid2}

    @pytest.mark.asyncio
    async def test_channel_subscribers_unknown_channel_returns_empty(self, server):
        async with ClientSession() as session:
            async with session.get(f"http://{HOST}:{HTTP_PORT}/channels/nonexistent/subscribers") as resp:
                assert resp.status == 200
                data = await resp.json()
                assert data == []


class TestChannelSubscription:
    @pytest.mark.asyncio
    async def test_subscribe_adds_to_channel(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            await ws.recv()
            await ws.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)
            assert "alerts" in _channels.list_channels()

    @pytest.mark.asyncio
    async def test_unsubscribe_removes_from_channel(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            await ws.recv()
            await ws.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)
            assert "alerts" in _channels.list_channels()

            await ws.send(json.dumps({
                "type": "unsubscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)
            assert "alerts" not in _channels.list_channels()

    @pytest.mark.asyncio
    async def test_client_can_subscribe_to_multiple_channels(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            await ws.recv()
            await ws.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "chat"}
            }))
            await ws.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)

            channels = _channels.list_channels()
            assert channels.get("chat") == 1
            assert channels.get("alerts") == 1

    @pytest.mark.asyncio
    async def test_disconnect_unsubscribes_from_all_channels(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws:
            await ws.recv()
            await ws.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await ws.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "chat"}
            }))
            await asyncio.sleep(0.1)
            assert "alerts" in _channels.list_channels()
            assert "chat" in _channels.list_channels()

        await asyncio.sleep(0.3)
        assert "alerts" not in _channels.list_channels()
        assert "chat" not in _channels.list_channels()


class TestChannelBroadcast:
    @pytest.mark.asyncio
    async def test_channel_message_only_delivers_to_subscribers(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws3:
            await ws1.recv()
            await ws2.recv()
            await ws3.recv()

            await ws1.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await ws2.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)

            await ws1.send(json.dumps({
                "type": "broadcast",
                "channel": "alerts",
                "payload": {"text": "alert!"}
            }))

            msg = json.loads(await asyncio.wait_for(ws2.recv(), timeout=2))
            assert msg["type"] == "broadcast"
            assert msg["payload"]["text"] == "alert!"

            with pytest.raises(asyncio.TimeoutError):
                await asyncio.wait_for(ws3.recv(), timeout=0.5)

    @pytest.mark.asyncio
    async def test_no_channel_messages_still_broadcast_to_all(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            await ws1.recv()
            await ws2.recv()

            await ws1.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)

            await ws1.send(json.dumps({
                "type": "broadcast",
                "payload": {"text": "everyone"}
            }))

            msg = json.loads(await asyncio.wait_for(ws2.recv(), timeout=2))
            assert msg["payload"]["text"] == "everyone"

    @pytest.mark.asyncio
    async def test_unsubscribe_stops_receiving_channel_messages(self, server):
        async with websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws1, \
                   websockets.connect(f"ws://{HOST}:{WS_PORT}") as ws2:
            await ws1.recv()
            await ws2.recv()

            await ws2.send(json.dumps({
                "type": "subscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)

            await ws1.send(json.dumps({
                "type": "broadcast",
                "channel": "alerts",
                "payload": {"text": "msg1"}
            }))
            msg = json.loads(await asyncio.wait_for(ws2.recv(), timeout=2))
            assert msg["payload"]["text"] == "msg1"

            await ws2.send(json.dumps({
                "type": "unsubscribe",
                "payload": {"channel": "alerts"}
            }))
            await asyncio.sleep(0.1)

            await ws1.send(json.dumps({
                "type": "broadcast",
                "channel": "alerts",
                "payload": {"text": "msg2"}
            }))

            with pytest.raises(asyncio.TimeoutError):
                await asyncio.wait_for(ws2.recv(), timeout=0.5)

